// UpdateMoby_1133: state machine that eases a value toward targets while the linked moby is alive.
void Moby1133Update(EaseMoby1C7C0 *moby) {
    EaseData1C7C0 *d = moby->data;
    EaseMoby1C7C0 *o;
    float v, w;
    if (d) {
        switch (moby->state) {
            case 0:
                moby->angle.i = 0;
                moby->state = 1;
                d->value.i = 0;
                break;
            case 1:
                if (d->target != -1 && (o = level_mobys_ease + d->target) != 0 && o->state != 0xFE &&
                    o->state != 0xFD && o->state != d->startState) {
                    return;
                }
                {
                    float dt = g_frame_time;
                    v = d->speed * dt;
                }
                d->value.f = v;
                moby->angle.f = v;
                Moby_PlaySound(0, 0, (int)moby);
                moby->state = 3;
                break;
            case 3:
                d->value.f = FastAddRots(d->value.f, FastCos(moby->angle.f) * (d->speed * g_frame_time));
                moby->angle.f = FastAddRots(moby->angle.f, d->value.f);
                o = level_mobys_ease + d->target;
                d->value.f = d->value.f * d->decay;
                if (o != 0 && o->state != 0xFE && o->state != 0xFD) {
                    if (o->state != d->endState) {
                        return;
                    }
                    moby->state = 4;
                }
                break;
            case 4:
                if (d->target == -1 || (o = level_mobys_ease + d->target) == 0 || o->state == 0xFE ||
                    o->state == 0xFD || o->state == d->startState) {
                    Moby_PlaySound(0, 0, (int)moby);
                    moby->state = 2;
                } else {
                    w = FastSubRots(moby->angle.f, d->limit);
                    moby->angle.f = w;
                    if (0.0f < w) {
                        moby->angle.f = 0.0f;
                        d->value.f = 0.0f;
                        moby->state = 1;
                    }
                }
                break;
            case 2:
            case 5:
                break;
        }
    }
}
