            int nj = (j + 1) % umbris_paths_r[d->path]->count;
            umbris_paths_r[d->path]->nodes[j].len =
                fast_vec_dist(&umbris_paths_r[d->path]->nodes[j], &umbris_paths_r[d->path]->nodes[nj]);
            d->total = d->total + umbris_paths_r[d->path]->nodes[j].len;
