// Runs the effect spawner: waits for the level flag, then emits sparks at four joints of a target moby.
void cutscene_effects_update(struct Moby *m) {
    int state = m->state;
    int a;
    int k;
    int t;
    int i;
    int j;
    char *mob;
    char *S;
    float buf[4];
    switch (state) {
        case 0:
            m->update_dist = 0xFF;
            m->state = 1;
            break;
        case 1:
            a = umbris_scene_state;
            if (a != 2)
                return;
            S = umbris_cutscene_state_c;
            t = *(int *)(S + 0x30) - 3;
            if ((unsigned)t < 2) {
                int idx = (unsigned)t > 1 ? 0 : 2;
                cutscene_set_camera_target(((L07SparkState *)S)->arr[idx]);
            }
            if (*(int *)(S + 0x30) != a)
                return;
            k = 7;
            if (*(int *)(S + 0x34) != scale_ticks(0xA8A))
                k = 0;
            if (*(int *)(S + 0x34) == scale_ticks(0xACE))
                k = 6;
            if (k != 0) {
                mob = (char *)((L07SparkState *)S)->arr[k];
                for (i = 0; i < 4; i++) {
                    moby_point_position(mob, i, buf);
                    for (j = 9; j >= 0; j--) {
                        float d = random_float_between(20000.0f, 200000.0f);
                        int col = (random_int_between(0x20, 0x80) << 24) | 0x7F7F7F;
                        int v = random_int_between(0, 4);
                        char *p;
                        char *q;
                        if (random_integer_below(2) != 0)
                            v = -v;
                        p = PartType23Spawn_v(buf, v, umbris_zero_vec, col, 0.6f, 1.0f, 1.01f, d);
                        if (p != 0) {
                            q = p + 0x20;
                            *(short *)(p + 0xA) = scale_ticks(random_int_between(0x3C, 0x5A));
                            *(int *)(q + 4) = 2;
                            *(char *)(q + 0xA) = col >> 24;
                            *(char *)(q + 0xB) = *(unsigned char *)(p + 0xA);
                        }
                    }
                }
            }
            break;
    }
}

/* Level moby state machine: wait, detect proximity, then emit effects, spawn a replacement and delete itself. */
void mushroom_update(char *m) {
    int hit = 0;
    struct HitMessage *r = (struct HitMessage *)MobyGetHitMessage(m, 0x10000, 0);
    struct Moby *n;
    char *d;
    char *p;
    char *q;
    switch (*(unsigned char *)(m + 0x20)) {
        case 0:
            m[0x20] = 1;
            break;
        case 1:
            if (r != 0 && r->damage > 0.0f)
                hit = 1;
            if (hit)
                m[0x20] = 2;
            break;
        case 2:
            Moby_PlaySound(0, 0, (int)m);
            d = umbris_zero_vec;
            spawn_proximity_gated_bolts(m);
            p = m + 0x10;
            q = m + 0x40;
            SpawnBreakFragment(m, 0x674, p, q, 0, 0, 0.0f, d, d, d);
            SpawnBreakFragment(m, 0x675, p, q, 0, 0, 0.0f, d, d, d);
            SpawnBreakFragment(m, 0x676, p, q, 0, 0, 0.0f, d, d, d);
            n = (struct Moby *)CreateMoby(0x673);
            if (n != 0) {
                n->visible = 1;
                n->draw_dist = 0xFF;
                qcopy(&n->pos, p);
                qcopy(&n->rot, q);
                *(long *)&n->spawn_frame = *(long *)(m + 0x38);
                moby_build_matrix(n);
            }
            DeleteMoby(m);
            break;
    }
}
