/* Stage machine for a three-state effect moby: wait, activate, burst and delete. */
void robot_head_update(char *self) {
    int flag = 0;
    struct HitMessage *o = (struct HitMessage *)MobyGetHitMessage(self, 0x10000, 0);
    switch (((unsigned char *)self)[0x20]) {
        case 0:
            self[0x20] = 1;
            break;
        case 1:
            if (o != 0 && o->damage > 0.0f) {
                flag = 1;
            }
            if (flag) {
                self[0x20] = 2;
            }
            break;
        case 2: {
            char *m;
            Moby_PlaySound(0, 0, (int)self);
            spawn_proximity_gated_bolts(self);
            SpawnBreakFragment(self, 0x68E, self + 0x10, self + 0x40, 0, 0, 0.0f, umbris_zero_vec, umbris_zero_vec,
                               umbris_zero_vec);
            SpawnBreakFragment(self, 0x68F, self + 0x10, self + 0x40, 0, 0, 0.0f, umbris_zero_vec, umbris_zero_vec,
                               umbris_zero_vec);
            SpawnBreakFragment(self, 0x690, self + 0x10, self + 0x40, 0, 0, 0.0f, umbris_zero_vec, umbris_zero_vec,
                               umbris_zero_vec);
            m = mk_a(0x68D);
            if (m != 0) {
                m[0x31] = 1;
                *(short *)(m + 0x32) = 0xFF;
                qcopy(m + 0x10, self + 0x10);
                qcopy(m + 0x40, self + 0x40);
                *(long *)(m + 0x38) = *(long *)(self + 0x38);
                moby_build_matrix(m);
            }
            DeleteMoby(self);
            break;
        }
    }
}

// Waits for a trigger, then spawns three effects at the moby and deletes it.
void seashell_update(unsigned char *m) {
    int flag = 0;
    float z;
    char *p, *pos, *vel;
    struct HitMessage *x = (struct HitMessage *)MobyGetHitMessage(m, 0x10000, 0);
    switch (m[0x20]) {
        case 0:
            m[0x20] = 1;
            break;
        case 1:
            if (x != 0) {
                if (x->damage > 0.0f)
                    flag = 1;
            }
            if (flag)
                m[0x20] = 2;
            break;
        case 2:
            Moby_PlaySound(0, 0, (int)m);
            z = 0.0f;
            p = umbris_zero_vec;
            pos = m + 0x10;
            spawn_proximity_gated_bolts(m);
            vel = m + 0x40;
            SpawnBreakFragment(m, 0x698, pos, vel, 0, 0, z, p, p, p);
            SpawnBreakFragment(m, 0x699, pos, vel, 0, 0, z, p, p, p);
            SpawnBreakFragment(m, 0x69A, pos, vel, 0, 0, z, p, p, p);
            DeleteMoby(m);
            break;
    }
}

